CREATE TABLE retrospective_checkpoints(project_id TEXT PRIMARY KEY REFERENCES projects(id), watermark INTEGER NOT NULL DEFAULT 0);
CREATE TABLE retrospective_batches(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), session_id TEXT NOT NULL, from_seq INTEGER NOT NULL, through_seq INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN('open','committed')), created_at TEXT NOT NULL, UNIQUE(project_id,id), FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id));
CREATE UNIQUE INDEX retrospective_open_batch ON retrospective_batches(project_id) WHERE status='open';
CREATE TABLE retrospective_epics(project_id TEXT PRIMARY KEY REFERENCES projects(id), ticket_id TEXT NOT NULL, FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id));
CREATE TABLE retrospective_groups(project_id TEXT NOT NULL REFERENCES projects(id), group_key TEXT NOT NULL, ticket_id TEXT, last_decision_id TEXT, PRIMARY KEY(project_id,group_key), FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id));
CREATE TABLE retrospective_decisions(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, batch_id TEXT NOT NULL, group_key TEXT NOT NULL, session_id TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN('now','milestone','observe')), observation TEXT NOT NULL, inferred_cause TEXT NOT NULL, rationale TEXT NOT NULL, revisit_trigger TEXT NOT NULL, review_after TEXT NOT NULL, ticket_id TEXT, recurrence_of TEXT, created_at TEXT NOT NULL, milestone_id TEXT NOT NULL, condition_text TEXT NOT NULL, UNIQUE(project_id,id), FOREIGN KEY(project_id,batch_id) REFERENCES retrospective_batches(project_id,id), FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id), FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id), FOREIGN KEY(project_id,recurrence_of) REFERENCES retrospective_decisions(project_id,id));
CREATE TABLE retrospective_citations(project_id TEXT NOT NULL, event_seq INTEGER NOT NULL REFERENCES events(seq), decision_id TEXT NOT NULL, PRIMARY KEY(project_id,event_seq), FOREIGN KEY(project_id,decision_id) REFERENCES retrospective_decisions(project_id,id));
CREATE TABLE retrospective_deferrals(project_id TEXT NOT NULL, ticket_id TEXT NOT NULL, milestone_id TEXT NOT NULL, condition_text TEXT NOT NULL, review_after TEXT NOT NULL, released_at TEXT, PRIMARY KEY(project_id,ticket_id), FOREIGN KEY(project_id,ticket_id) REFERENCES tickets(project_id,id));
CREATE TABLE retrospective_effectiveness(id TEXT PRIMARY KEY, project_id TEXT NOT NULL, decision_id TEXT NOT NULL, session_id TEXT NOT NULL, outcome TEXT NOT NULL CHECK(outcome IN('improved','unchanged','worse','unknown')), evidence TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(project_id,decision_id) REFERENCES retrospective_decisions(project_id,id), FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id));
CREATE INDEX retrospective_problem_events ON events(project_id,seq) WHERE kind IN('problem.add','problem.append');
